-- Isolated g3_ runner only. Never loaded by accepted G1/G2 migration runners.
CREATE TABLE g3_runs(id uuid PRIMARY KEY,room_id uuid NOT NULL,epoch uuid NOT NULL,config_revision integer NOT NULL,owner_id uuid NOT NULL REFERENCES accounts(id),state text NOT NULL CHECK(state IN ('running','ended')),mode text NOT NULL CHECK(mode='core'));
CREATE TABLE g3_access(run_id uuid REFERENCES g3_runs(id),principal_id uuid REFERENCES accounts(id),display_name text NOT NULL CHECK(octet_length(display_name)<=80),PRIMARY KEY(run_id,principal_id));
CREATE TABLE g3_contexts(attachment_id uuid PRIMARY KEY,run_id uuid NOT NULL REFERENCES g3_runs(id),principal_id uuid NOT NULL REFERENCES accounts(id),game_session_id uuid NOT NULL UNIQUE REFERENCES sessions(id),session_epoch uuid NOT NULL,service_epoch uuid NOT NULL,world_token text NOT NULL CHECK(octet_length(world_token) BETWEEN 1 AND 80),capabilities text[] NOT NULL,presence_until timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE g3_balances(run_id uuid PRIMARY KEY REFERENCES g3_runs(id),amount bigint NOT NULL DEFAULT 0 CHECK(amount BETWEEN 0 AND 4294967295));
CREATE TABLE g3_operations(run_id uuid REFERENCES g3_runs(id),principal_id uuid REFERENCES accounts(id),operation_id uuid,attachment_id uuid NOT NULL REFERENCES g3_contexts(attachment_id),world_token text NOT NULL,direction text NOT NULL CHECK(direction IN ('deposit','withdraw')),amount integer NOT NULL CHECK(amount BETWEEN 1 AND 1000000),digest text NOT NULL CHECK(length(digest)=64),delivery_id uuid NOT NULL UNIQUE,state text NOT NULL CHECK(state IN ('awaiting_local','reserved','uncertain','completed','cancelled')),local_outcome text NOT NULL DEFAULT 'unknown',created_at timestamptz NOT NULL,PRIMARY KEY(run_id,principal_id,operation_id));
CREATE TABLE g3_ledger(sequence bigserial PRIMARY KEY,run_id uuid NOT NULL,principal_id uuid NOT NULL,operation_id uuid NOT NULL,delta bigint NOT NULL,balance bigint NOT NULL CHECK(balance BETWEEN 0 AND 4294967295),created_at timestamptz NOT NULL,UNIQUE(run_id,principal_id,operation_id),FOREIGN KEY(run_id,principal_id,operation_id) REFERENCES g3_operations);
CREATE TABLE g3_receipts(run_id uuid,principal_id uuid,operation_id uuid,receipt_id uuid,fingerprint text NOT NULL,evidence_digest text NOT NULL CHECK(length(evidence_digest)=64),outcome text NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY(run_id,principal_id,operation_id,receipt_id),FOREIGN KEY(run_id,principal_id,operation_id) REFERENCES g3_operations);
CREATE TABLE g3_outbox(sequence bigserial PRIMARY KEY,run_id uuid NOT NULL,principal_id uuid NOT NULL,kind text NOT NULL,body jsonb NOT NULL CHECK(octet_length(body::text)<=8192),created_at timestamptz NOT NULL);
CREATE INDEX g3_outbox_delivery ON g3_outbox(run_id,principal_id,sequence);
CREATE TABLE g3_events(run_id uuid,principal_id uuid,event_id uuid,digest text NOT NULL,PRIMARY KEY(run_id,principal_id,event_id));
CREATE TABLE g3_statistics(sequence bigserial PRIMARY KEY,run_id uuid NOT NULL REFERENCES g3_runs(id),principal_id uuid NOT NULL,display_name text NOT NULL CHECK(octet_length(display_name)<=80),version integer NOT NULL CHECK(version=1),kind text NOT NULL,count integer NOT NULL CHECK(count BETWEEN 0 AND 1000000),provenance text NOT NULL CHECK(provenance IN ('service-committed','validated-client-report')),captured_at timestamptz NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX g3_statistics_page ON g3_statistics(run_id,sequence);
CREATE INDEX g3_statistics_retention ON g3_statistics(expires_at,sequence);
CREATE FUNCTION g3_immutable_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'G3 audit records are append only'; END $$;
CREATE TRIGGER g3_ledger_immutable BEFORE UPDATE OR DELETE ON g3_ledger FOR EACH ROW EXECUTE FUNCTION g3_immutable_audit();
CREATE TRIGGER g3_receipts_immutable BEFORE UPDATE OR DELETE ON g3_receipts FOR EACH ROW EXECUTE FUNCTION g3_immutable_audit();
INSERT INTO schema_migrations(version) VALUES(101);
